/** The subset of `userIds` holding a live, active membership in the org. */
export async function filterActiveUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<readonly UserId[]> {
  if (userIds.length === 0) return [];
  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .all();
  const live = new Set(rows.map((row) => row.userId));
  return userIds.filter((id) => live.has(id));
}

/** Re-admits an archived membership: same row, fresh role, inviter and join date. */
export async function reactivateMember(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
  invitedBy: UserId | null,
  at: IsoTimestamp,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
